  "body": "  Run the code below to see the turtle draw a square. Change the code to delete the repeated lines by using a for loop to draw a side of the square four times.    import turtle tina = turtle.Turtle() tina.shape(\"turtle\") tina.color(\"green\") tina.penup() tina.goto(-150,150) # move turtle up tina.pendown() # Change this code to use a for-loop to make tina go forward and turn tina.forward(100) tina.right(90) tina.forward(100) tina.right(90) tina.forward(100) tina.right(90) tina.forward(100)  from unittest.gui import TestCaseGui class myTests(TestCaseGui): def test1(self): self.assertIn(\"for \",self.getEditorText(), \"Use a for loop to repeat the forward and right commands\") self.assertIn(\"range(4)\",self.getEditorText(), \"Use range(4) to repeat 4 times\") input_count = self.getEditorText().count(\".forward\") self.assertEqual(1, input_count, \"Use just 1 forward\") input_count = self.getEditorText().count(\".right\") self.assertEqual(1, input_count, \"Use just 1 right turn\") myTests().main()   "
